# -*- coding: utf-8 -*-
import os
import subprocess

root = r"c:/Users/win/Desktop/敖钦储能项目"
out = subprocess.check_output(
    ["git", "status", "--porcelain", "-u"],
    cwd=root,
    text=True,
    encoding="utf-8",
    errors="replace",
)
paths = []
for line in out.splitlines():
    p = line[3:].strip().strip('"')
    if " -> " in p:
        p = p.split(" -> ")[-1]
    if p:
        paths.append(p)

total = 0
for p in paths:
    fp = os.path.join(root, p)
    if os.path.isfile(fp):
        total += os.path.getsize(fp)
    elif os.path.isdir(fp):
        for dp, _dns, fns in os.walk(fp):
            for f in fns:
                try:
                    total += os.path.getsize(os.path.join(dp, f))
                except OSError:
                    pass

print(f"changed_paths={len(paths)}")
print(f"approx_MB={total / 1024 / 1024:.1f}")
